INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9401, '2 Kings 16:2', '2 Kings', 16, 2, '&nbsp;چې عُمر يې شل کاله وو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه. هغۀ هغه کار نۀ کولو چې د مالِک خُدائ د هغۀ د خُدائ پاک په نظر کښې ښۀ وو، اګر چې د هغۀ پلار نيکۀ داؤد ښۀ کارونه کړى وُو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9402, '2 Kings 16:3', '2 Kings', 16, 3, '&nbsp;خو د اِسرائيل بادشاهانو په مِثالونو يې دومره عمل کولو، چې خپل زوئ يې هم په اور کښې قربانى کړو، او د هغه خلقو پليت رِواج يې خپل کړے وو کوم چې مالِک خُدائ د هغه مُلک نه ويستلى وُو کله چې اِسرائيليان مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9403, '2 Kings 16:4', '2 Kings', 16, 4, '&nbsp;په غرونو باندې او د هرې ونې د سورى لاندې، او په علاقائى عبادتخانو احاز قربانۍ پېش کولې او خوشبوئى يې سوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9404, '2 Kings 16:5', '2 Kings', 16, 5, '&nbsp;د شام بادشاه رضين او د اِسرائيل بادشاه فقح په يروشلم باندې حمله وکړه او دا يې محاصره کړو، خو احاز له يې شکست نۀ شو ورکولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9405, '2 Kings 16:6', '2 Kings', 16, 6, '&nbsp;هم په هغه وخت، د ادوم بادشاه د ايلات ښار بيا ونيولو او د يهوداه اوسېدونکى يې د هغې ځائ نه وشړل. ادوميان په ايلات کښې دېره شول او تر اوسه پورې هلته اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9406, '2 Kings 16:7', '2 Kings', 16, 7, '&nbsp;احاز د اسور بادشاه تغلت فلاسر له د دې پېغام سره سړى ولېږل، ”زۀ ستاسو وقف شوے خِدمت کوونکے يم. راشه او ما د شام او اِسرائيل د بادشاهانو د حملې نه بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9407, '2 Kings 16:8', '2 Kings', 16, 8, '&nbsp;احاز د مالِک خُدائ د کور او د محل د خزانې نه سرۀ زر او سپين زر هم واخستل او بادشاه له يې د محصُول په توګه ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9408, '2 Kings 16:9', '2 Kings', 16, 9, '&nbsp;د احاز د غوښتنې په جواب کښې تغلت فلاسر د دمشق خِلاف د خپل لښکر سره روان شو، دا يې قبضه کړو او رضين بادشاه يې ووژلو او خلق يې قير ته قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9409, '2 Kings 16:10', '2 Kings', 16, 10, '&nbsp;کله چې احاز بادشاه د تغلت فلاسر سره د مِلاوېدو دپاره دمشق ته لاړو، نو هلته يې قربان‌ګاه وليده او اورِياه اِمام له يې هم د دې په شان نمونه او ټول تفصيل ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9410, '2 Kings 16:11', '2 Kings', 16, 11, '&nbsp;نو اورِياه هم د دې په شان يوه قربان‌ګاه جوړه کړه او د احاز د واپسۍ نه مخکښې يې دا تياره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9411, '2 Kings 16:12', '2 Kings', 16, 12, '&nbsp;د دمشق نه په واپسۍ باندې، احاز وليدل چې قربان‌ګاه جوړه وه نو قربانى ورباندې پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9412, '2 Kings 16:13', '2 Kings', 16, 13, '&nbsp;هغۀ په دې باندې د ځناورو سوزېدونکې قربانۍ او د غلې نذرانې پېش کړې او په دې باندې يې د ميو نذرانه توئ کړه او د وينې د سلامتۍ نذرانه يې ورباندې واچوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9413, '2 Kings 16:14', '2 Kings', 16, 14, '&nbsp;مالِک خُدائ ته وقف شوې د زېړو قربان‌ګاه د نوې قربان‌ګاه او د مالِک خُدائ د کور په مينځ کښې وه، نو احاز دا د خپلې نوې قربان‌ګاه شمالى طرف ته يوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9414, '2 Kings 16:15', '2 Kings', 16, 15, '&nbsp;بيا هغۀ اورِياه ته حُکم وکړو، ”دا لويه قربان‌ګاه د سحر سوزېدونکې نذرانې او د ماښام د غلې نذرانې دپاره استعمالوه او د بادشاه او د خلقو د سوزېدونکې نذرانې، د غلې نذرانې او د خلقو د څښلو نذرانې دپاره يې استعمالوه. په دې باندې د هغه ټولو ځناورو وينه تويوه چې کوم قربانى شوى وى. خو د زېړو قربان‌ګاه زما دپاره وساته چې د فال دپاره يې استعمالوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9415, '2 Kings 16:16', '2 Kings', 16, 16, '&nbsp;نو اورِياه هم هغه شان وکړل چې څنګه بادشاه حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9416, '2 Kings 16:17', '2 Kings', 16, 17, '&nbsp;احاز بادشاه د زېړو هغه تختې او هغه ښانکونه لرې کړل، هغۀ د زېړو د دولسو غوَيو د شا نه د زېړو ډيګۍ هم واخستله او دا يې د کاڼى په بنياد کېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9417, '2 Kings 16:18', '2 Kings', 16, 18, '&nbsp;د اسور بادشاه د خوشحالولو دپاره، احاز د مالِک خُدائ د کور نه د سبت د ورځې د شاهى تخت نه پاس دالان هم لرې کړو او د مالِک خُدائ د کور د بادشاه د ننوتلو ذاتى دروازه يې بنده کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9418, '2 Kings 16:19', '2 Kings', 16, 19, '&nbsp;نور هر څۀ چې احاز بادشاه کړى دى هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9419, '2 Kings 16:20', '2 Kings', 16, 20, '&nbsp;احاز مړ شو او د داؤد ښار په شاهى اديره کښې ښخ شو او د هغۀ زوئ حزقياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9420, '2 Kings 17:1', '2 Kings', 17, 1, '&nbsp;د يهوداه بادشاه احاز د بادشاهۍ په دولسم کال، د ايله زوئ هوسيع د اِسرائيل بادشاه شو او هغۀ په سامريه کښې نهۀ کاله حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9421, '2 Kings 17:2', '2 Kings', 17, 2, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه وکړه، خو دا د هغه بادشاهانو هومره نۀ وه چا چې د هغۀ نه مخکښې په اِسرائيل حکومت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9422, '2 Kings 17:3', '2 Kings', 17, 3, '&nbsp;د اسور بادشاه سلمنسر د هوسيع خِلاف جنګ وکړو، هوسيع د سلمنسر د اختيار لاندې راغلو او هوسيع به هر کال هغۀ له محصُول ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9423, '2 Kings 17:4', '2 Kings', 17, 4, '&nbsp;خو يو کال هوسيع د مِصر بادشاه سو له پېغام وړُونکى ولېږل او د هغۀ نه يې مدد وغوښتو او اسور له د هر کال محصُول ورکول بند کړل. کله چې سلمنسر د دې نه خبر شو، نو هغۀ هوسيع ونيولو او په قېدخانه کښې يې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9424, '2 Kings 17:5', '2 Kings', 17, 5, '&nbsp;بيا سلمنسر په اِسرائيل حمله وکړه او سامريه يې محاصره کړو. د محاصرې په درېم کال،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9425, '2 Kings 17:6', '2 Kings', 17, 6, '&nbsp;چې دا د هوسيع د بادشاهۍ نهم کال وو، د اسور بادشاه سامريه قبضه کړه، د اِسرائيل خلق يې اسور ته قېديان بوتلل او د هغوئ څۀ کسان په خلح ښار کښې، څۀ د جوزان په ضِلع کښې د خابور سيند سره نزدې او څۀ د ماديو ښارونو ته د اوسېدو دپاره ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9426, '2 Kings 17:7', '2 Kings', 17, 7, '&nbsp;د سامريه زوال ځکه وشو چې بنى اِسرائيلو د مالِک خُدائ د خپل خُدائ پاک خِلاف ګناه کړې وه، چا چې هغوئ د مِصر بادشاه فِرعون نه خلاص کړل او د مِصر نه يې راوويستل. هغوئ د نورو خُدايانو عبادت وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9427, '2 Kings 17:8', '2 Kings', 17, 8, '&nbsp;او د هغه خلقو رِواجونه يې خپل کړل چې مالِک خُدائ په هغه وخت شړلى وُو چې اِسرائيليان مخ په وړاندې تلل او چې د اِسرائيل بادشاهانو کوم رِواجونه شروع کړى وُو نو هغه يې هم خپل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9428, '2 Kings 17:9', '2 Kings', 17, 9, '&nbsp;اِسرائيليانو په پټه باندې هغه کارونه وکړل کوم چې مالِک خُدائ د هغوئ خُدائ پاک منع کړى وُو. هغوئ د وړو ښارونو نه واخله تر پَخو ښارونو پورې د ځان دپاره علاقائى عبادتخانې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9429, '2 Kings 17:10', '2 Kings', 17, 10, '&nbsp;هغوئ په ټولو غرونو باندې او د هرې ونې د سورى لاندې د کاڼو ستنې او د اشيرې د بُت نښې کېښودې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9430, '2 Kings 17:11', '2 Kings', 17, 11, '&nbsp;او د هغوئ په هره علاقائى عبادتخانې کښې خوشبوئى سوزولې لکه څنګه به چې غېر قومونو کول کوم خلق چې مالِک خُدائ د هغه مُلک نه شړلى وُو. هغوئ د خپلو ټولو بدو عملونو په وجه د مالِک خُدائ قهر راوپارولو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9431, '2 Kings 17:12', '2 Kings', 17, 12, '&nbsp;او د مالِک خُدائ د هغه حُکم نافرمانى يې وکړه چې د بُتانو عبادت مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9432, '2 Kings 17:13', '2 Kings', 17, 13, '&nbsp;د يهوداه او اِسرائيل د خبردارى دپاره مالِک خُدائ پېغام وړُونکى او نبيان لېږلى وُو چې هغوئ فرمائيل، ”خپل بد عملونه پرېږدئ او زما حُکمونه ومنئ، چې په هغې کښې هغه شريعت شامل دے چې کوم ما ستاسو پلار نيکۀ له ورکړے وو او د خپلو خِدمت کوونکو پېغمبرانو په ذريعه مې ستاسو په حواله کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9433, '2 Kings 17:14', '2 Kings', 17, 14, '&nbsp;خو هغوئ به د هغۀ په وېنا باندې عمل نۀ کولو، هغوئ د خپل پلار نيکۀ په شان ضديان وُو، چا چې په مالِک خُدائ خپل خُدائ پاک باندې يقين نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9434, '2 Kings 17:15', '2 Kings', 17, 15, '&nbsp;هغوئ هغه اصُول ونۀ منل او هغه لوظ يې پوره نۀ کړو کوم يې چې د هغوئ د پلار نيکۀ سره کړے وو او هغوئ د هغۀ خبردارى ته پام ونۀ کړو. هغوئ د غلطو بُتانو عبادت وکړو او خپل ځانونه يې سپک کړل، هغوئ د ګېرچاپېره قومونو په رِواجونو باندې روان وُو او د مالِک خُدائ د هغه حُکم نافرمانى يې وکړه چې د هغوئ د رِواج نقل مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9435, '2 Kings 17:16', '2 Kings', 17, 16, '&nbsp;هغوئ د مالِک خُدائ د خپل خُدائ پاک ټول قانون مات کړو او د ځان دپاره يې د سخو په شکل کښې دوه د سرو زور بُتان جوړ کړل، هغوئ د اشيرې بُت نښه هم جوړه کړه، د ستورو عبادت يې وکړو او د بعل بُت خِدمت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9436, '2 Kings 17:17', '2 Kings', 17, 17, '&nbsp;هغوئ خپل زامن او لوڼه د غېرو قومونو خُدايانو ته د سوزېدونکې نذرانې په توګه قربانى کړل، هغوئ د فالګرو او قسمت ښودونکو سره مشورې وکړې او هغوئ خپل ځانونه هغه څۀ ته حواله کړل چې څۀ د مالِک خُدائ په نظر کښې غلط وُو او په دې کولو سره يې د هغۀ قهر راوپارولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9437, '2 Kings 17:18', '2 Kings', 17, 18, '&nbsp;مالِک خُدائ اِسرائيل ته غصه وو او د خپل حضور نه يې لرې کړل او صِرف د يهوداه بادشاهى يې په ځائ پرېښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9438, '2 Kings 17:19', '2 Kings', 17, 19, '&nbsp;خو د يهوداه خلقو هم د مالِک خُدائ د خپل خُدائ پاک قانون ونۀ منلو، هغوئ د هغه رِواجونو نقل شروع کړو چې کوم اِسرائيل خپل کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9439, '2 Kings 17:20', '2 Kings', 17, 20, '&nbsp;مالِک خُدائ ټول اِسرائيل رد کړو، هغوئ له يې سزا ورکړه او ظالمانو دشمنانو ته يې حواله کړل او په آخر کښې يې د خپل حضور نه وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9440, '2 Kings 17:21', '2 Kings', 17, 21, '&nbsp;کله چې مالِک خُدائ اِسرائيل د يهوداه نه جدا کړو، نو اِسرائيل د نباط زوئ يربعام خپل بادشاه جوړ کړو. يربعام په هغوئ باندې مالِک خُدائ پرېښودو او په هغوئ باندې يې کبيره ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9441, '2 Kings 17:22', '2 Kings', 17, 22, '&nbsp;هغوئ په يربعام پسې روان وُو او چې هغۀ کوم ګناهونه کړى وُو نو هغه ټول يې کول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9442, '2 Kings 17:23', '2 Kings', 17, 23, '&nbsp;چې په آخر کښې مالِک خُدائ هغوئ د خپل حضور نه لرې کړل، لکه څنګه چې هغۀ د خپلو خِدمت کوونکو پېغمبرانو په ذريعه خبردارے ورکړے وو چې داسې به وکړى. نو د اِسرائيل خلق اسور ته جلاوطن کړے شول، چرته چې تر اوسه پورې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9443, '2 Kings 17:24', '2 Kings', 17, 24, '&nbsp;د اسور بادشاه د بابل، کُوت، عِواه، حمات او سفروائم ښارونو نه خلق بوتلل او د سامريه په ښارونو کښې يې د اِسرائيل د خلقو په ځائ دېره کړل. هغوئ دا ښارونه قبضه کړل او هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9444, '2 Kings 17:25', '2 Kings', 17, 25, '&nbsp;کله چې هغوئ هلته اوسېدل نو په شروع کښې هغوئ د مالِک خُدائ عبادت نۀ کولو، نو هغۀ ازمرى ورولېږل. او زمريانو د هغوئ نه څۀ کسان ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9445, '2 Kings 17:26', '2 Kings', 17, 26, '&nbsp;د اسور بادشاه ته وئيلى شوى وُو چې کوم خلق هغۀ د سامريه په ښارونو کښې آباد کړى دى هغوئ د هغه مُلک د معبود په قانون باندې نۀ پوهيږى، نو ځکه هغه معبود ازمرى رالېږلى وُو چې هغوئ يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9446, '2 Kings 17:27', '2 Kings', 17, 27, '&nbsp;نو هغه بادشاه حُکم وکړو چې، ”د هغه اِمامانو نه يو راولېږه چې کوم مونږ قېديان راوستى دى، هغه دې لاړ شى او هلته دې اوسيږى، چې خلقو ته د هغه مُلک د خُدائ قانون وښائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9447, '2 Kings 17:28', '2 Kings', 17, 28, '&nbsp;نو يو اِسرائيلے اِمام لاړو چې کوم د سامريه نه راويستلے شوے وو او په بيت‌ايل کښې د اوسېدو دپاره لاړل، هلته يې خلقو ته دا ښودنه کوله چې د مالِک خُدائ عبادت به څنګه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9448, '2 Kings 17:29', '2 Kings', 17, 29, '&nbsp;خو چې کوم خلق په سامريه کښې اوسېدل نو هر يو قوم خپل قومى بُتان جوړ کړل او دا يې په هغه علاقائى زيارتونو کښې کېښودل چې اِسرائيليانو جوړ کړى وُو. او هرې قبيلې په خپل خپل ښار کښې بُتان جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9449, '2 Kings 17:30', '2 Kings', 17, 30, '&nbsp;د بابل خلقو د سُکات بنات بُتان جوړ کړل، د کُوت خلقو، د نيرګل بُتان، د حمات خلقو، د اسيما بُتان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9450, '2 Kings 17:31', '2 Kings', 17, 31, '&nbsp;د عِواه خلقو، د نِبحاز او ترتاق بُتان، او د سفروائم خلقو خپل بچى د ادرمُلِک او عنمُلک خُدايانو ته د سوزېدونکې نذرانې په توګه قربانى کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9451, '2 Kings 17:32', '2 Kings', 17, 32, '&nbsp;دې خلقو د مالِک خُدائ عبادت هم کولو خو د هر قِسم خلقو نه يې اِمامان خوښ کړل چې په علاقائى عبادتخانو کښې د هغوئ دپاره نذرانې پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9452, '2 Kings 17:33', '2 Kings', 17, 33, '&nbsp;نو هغوئ د مالِک خُدائ عبادت کولو، خو چې هغوئ د کومو مُلکونو نه راغلى وُو د هغې د رِواجونو په مطابق يې د خپلو خُدايانو عبادت هم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9453, '2 Kings 17:34', '2 Kings', 17, 34, '&nbsp;هغوئ تر نن ورځې پورې هغه رِواجونه کوى. هغوئ نۀ د مالِک خُدائ عبادت کوى او نۀ د هغه قانون او حُکمونه منى چې کوم يې د يعقوب اولاد له ورکړى وُو، يعقوب له اِسرائيل نوم ورکړے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9454, '2 Kings 17:35', '2 Kings', 17, 35, '&nbsp;مالِک خُدائ د هغوئ سره يو لوظ کړے وو او هغوئ له يې حُکم ورکړ‌ے وو چې، ”د نورو معبودانو عبادت مۀ کوئ، هغوئ ته سجده مۀ کوئ، د هغوئ خِدمت مۀ کوئ او هغوئ ته قربانى مۀ پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9455, '2 Kings 17:36', '2 Kings', 17, 36, '&nbsp;تاسو دې زما يعنې مالِک خُدائ تابعدارى کوئ، چا چې د لوئ طاقت او قوت سره د مِصر نه راوويستلئ، تاسو به ما ته سجده کوئ او ما ته به قربانى پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9456, '2 Kings 17:37', '2 Kings', 17, 37, '&nbsp;تاسو به همېشه هغه قانون او حُکمونه منئ چې کوم ما درته ليکلى دى. تاسو دې د نورو خُدايانو عبادت ونۀ کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9457, '2 Kings 17:38', '2 Kings', 17, 38, '&nbsp;او تاسو هغه لوظ مۀ هېروئ چې کوم ما درسره کړے دے. او چې تاسو د نورو معبودانو عبادت ونۀ کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9458, '2 Kings 17:39', '2 Kings', 17, 39, '&nbsp;خو تاسو زما، يعنې د مالِک خُدائ د خپل خُدائ پاک عبادت کوئ او زۀ به تاسو د خپلو دشمنانو نه بچ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9459, '2 Kings 17:40', '2 Kings', 17, 40, '&nbsp;خو هغه خلقو به غوږ نۀ نيولو او په خپلو زړو رِواجونو باندې يې عمل کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9460, '2 Kings 17:41', '2 Kings', 17, 41, '&nbsp;نو هغه خلقو د مالِک خُدائ عبادت کولو، د خپلو بُتانو عبادت يې هم کولو، نو د هغوئ اولاد تر نن ورځې پورې هم دغه کار نۀ پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9461, '2 Kings 18:1', '2 Kings', 18, 1, '&nbsp;نو د اِسرائيل بادشاه د ايله زوئ هوسيع د بادشاهۍ په درېم کال د احاز زوئ حزقياه د يهوداه بادشاه جوړ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9462, '2 Kings 18:2', '2 Kings', 18, 2, '&nbsp;چې عُمر يې پينځويشت کاله وو او په يروشلم باندې يې نهۀ‌ويشت کاله بادشاهى وکړه. د هغۀ مور ابياه د زکرياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9463, '2 Kings 18:3', '2 Kings', 18, 3, '&nbsp;د خپل پلار نيکۀ داؤد په مِثالونو يې عمل وکړو، هغۀ هغه کار کولو چې د مالِک خُدائ په نظر کښې ښۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9464, '2 Kings 18:4', '2 Kings', 18, 4, '&nbsp;هغۀ علاقائى عبادتخانې تباه کړى، د کاڼى ستنې يې ماتې کړې او د اشيرې بُت نښې يې راوغورزولې. هغۀ د زېړو مار هم ټوټې ټوټې کړو چې موسىٰ جوړ کړے وو، چې نوم يې نحشتان وو. ځکه چې تر اوسه پورې اِسرائيلو دې ته خوشبوئى سوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9465, '2 Kings 18:5', '2 Kings', 18, 5, '&nbsp;حزقياه په مالِک خُدائ د بنى اِسرائيلو په خُدائ پاک باندې ايمان لرلو، په يهوداه کښې د هغۀ په شان بل بادشاه نۀ مخکښې او نۀ وروستو تېر شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9466, '2 Kings 18:6', '2 Kings', 18, 6, '&nbsp;هغه د مالِک خُدائ وفادار وو او هيڅکله يې د هغۀ نافرمانى نۀ وه کړې او هغه ټول حُکمونه يې پوره منل چې مالِک خُدائ موسىٰ له ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9467, '2 Kings 18:7', '2 Kings', 18, 7, '&nbsp;نو مالِک خُدائ د هغۀ مل وو او هغه په هر کار کښې کامياب وو. هغۀ د اسور د بادشاه خِلاف بغاوت وکړو او د هغۀ خِدمت يې نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9468, '2 Kings 18:8', '2 Kings', 18, 8, '&nbsp;هغۀ فلستيانو له شکست ورکړو او د وړوکى کلى نه واخله تر لوئ ښار پورې يې قبضه کړل چې په دې کښې غزه او ګېرچاپېره علاقه شامله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9469, '2 Kings 18:9', '2 Kings', 18, 9, '&nbsp;د حزقياه د بادشاهۍ په څلورم کال، چې په اِسرائيل باندې د هوسيع د بادشاهۍ اوؤم کال وو، د اسور بادشاه سلمنسر په اِسرائيل حمله وکړه او سامريه يې محاصره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9470, '2 Kings 18:10', '2 Kings', 18, 10, '&nbsp;د محاصرې په درېم کال، د سامريه زوال وشو، دا د حزقياه د بادشاهۍ شپږم کال وو او د هوسيع د بادشاهۍ نهم کال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9471, '2 Kings 18:11', '2 Kings', 18, 11, '&nbsp;د اسور بادشاه د اِسرائيل خلق اسور ته قېديان بوتلل او د هغوئ څۀ کسان په خلع ښار کښې، څۀ د خابور سيند سره نزدې د جوزان په ضِلع کښې او څۀ د ماديو په ښارونو کښې يې آباد کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9472, '2 Kings 18:12', '2 Kings', 18, 12, '&nbsp;د سامريه زوال ځکه وشو چې د اِسرائيل خلق د مالِک خُدائ د خپل خُدائ پاک تابعدارى نۀ کوله او هغۀ سره يې کړے لوظ مات کړو او د هغه ټول قانون نافرمانى يې وکړه چې خپل خِدمت کوونکى موسىٰ له يې ورکړے وو. هغوئ به نۀ ورته غوږ نيولو او نۀ به يې پرې عمل کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9473, '2 Kings 18:13', '2 Kings', 18, 13, '&nbsp;د حزقياه بادشاه د بادشاهۍ په څوارلسم کال، د اسور بادشاه سينحرب، د يهوداه په پَخو دېوالونو په ښارونو باندې حمله وکړه او فتح يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9474, '2 Kings 18:14', '2 Kings', 18, 14, '&nbsp;حزقياه سينحرب بادشاه له يو پېغام ولېږلو، چې هغه په لکيس کښې وو، ”زما نه غلطى شوې ده، مِهربانى وکړه چې خپله حمله بنده کړه او چې تۀ څومره پېسې غواړې نو زۀ به يې درکړم.“ نو بادشاه ترې نه وغوښتل چې حزقياه هغۀ له لس زره کلو سپين زر او زر کلو سرۀ زر ورولېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9475, '2 Kings 18:15', '2 Kings', 18, 15, '&nbsp;نو حزقياه هغۀ ته د مالِک خُدائ د کور او د محل د خزانې ټول سپين زر ورولېږل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9476, '2 Kings 18:16', '2 Kings', 18, 16, '&nbsp;هغۀ د مالِک خُدائ کور د دروازو نه او هغه سرۀ زر هم راوشوکول چې هغۀ ورباندې په خپله چوکاټونه پټ کړى وُو او سينحرب له يې ورولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9477, '2 Kings 18:17', '2 Kings', 18, 17, '&nbsp;د اسور بادشاه د لکيس نه يو لوئ لښکر ولېږلو چې په يروشلم کښې په حزقياه باندې حمله وکړى، چې د دې مشرى د هغۀ درې غټو آفسرانو کوله. کله چې هغوئ يروشلم ته ورسېدل، نو هغوئ د ولې سره سړک قبضه کړو چې په دې کښې د بره ډنډ نه اوبۀ راتلې، دا د هغه سړک سره نزدې وو چې کوم د دهوبى پټى ته تلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9478, '2 Kings 18:18', '2 Kings', 18, 18, '&nbsp;کله چې هغوئ حزقياه بادشاه راوغوښتلو، نو د هغۀ درې آفسران د هغوئ سره مِلاوېدو دپاره ور ووتل يعنې، د خِلقياه زوئ اِلياقيم، چې هغه د محل مشر وو، شبناه، د دربار منشى، او د آسف زوئ يوآخ، چې د حِساب کِتاب مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9479, '2 Kings 18:19', '2 Kings', 18, 19, '&nbsp;يو اسورى آفسر هغوئ ته ووئيل چې، ”بادشاه په دې باندې پوهېدل غواړى چې حزقياه په څۀ باندې ايمان لرى چې دومره اعتبارى دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9480, '2 Kings 18:20', '2 Kings', 18, 20, '&nbsp;ستا په خيال تشې خبرې د فوجى تکړه‌توب او طاقت ځائ نيولے شى؟ ستا يقين په چا دے چې زما خِلاف بغاوت کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9481, '2 Kings 18:21', '2 Kings', 18, 21, '&nbsp;تۀ د مِصر نه دا طمع کوې چې هغه به ستا مدد وکړى، خو دا به د لوخې د پاڼې د امسا په شان وى، چې لاس به دې غوڅ او زخمى کړى. نو د مِصر بادشاه فِرعون باندې چې کله څوک بهروسه وکړى نو هغه داسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9482, '2 Kings 18:22', '2 Kings', 18, 22, '&nbsp;يا به تۀ ما ته دا ووائې چې تۀ په مالِک خُدائ په خپل خُدائ پاک باندې بهروسه کوې. خو دا هغه خُدائ پاک نۀ دے چې حزقياه د هغۀ علاقائى عبادتخانې او قربان‌ګاه ختمې کړې، او هغۀ د يهوداه او د يروشلم خلقو ته وفرمائيل چې صِرف په يروشلم کښې د قربان‌ګاه سره عبادت کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9483, '2 Kings 18:23', '2 Kings', 18, 23, '&nbsp;نو خبره واورئ، زما د نېک د اسور بادشاه سره معاهده وکړئ، زۀ به تاسو له دوه زره آسونه درکړم کۀ تاسو دومره سړى پېدا کړل چې په دې باندې سوارۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9484, '2 Kings 18:24', '2 Kings', 18, 24, '&nbsp;تۀ د اسور د يو معمولى آفسر برابر هم نۀ يئ او تۀ بيا هم په طمع يې چې مِصريان به جنګى ګاډۍ او آسونه راولېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9485, '2 Kings 18:25', '2 Kings', 18, 25, '&nbsp;ستا په خيال ما د مالِک خُدائ د مدد نه بغېر ستا په مُلک حمله کړې ده او تباه کړے مې دے؟ ما ته مالِک خُدائ په خپله فرمائيلى دى چې په دې باندې حمله وکړم او تباه يې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9486, '2 Kings 18:26', '2 Kings', 18, 26, '&nbsp;نو اِلياقيم، شبناه او يوآخ هغه آفسر ته ووئيل، ”تۀ د خپلو نوکرانو سره په آرامى ژبه کښې خبرې وکړه، مونږ په دې پوهيږو. مونږ سره په عبرانۍ کښې خبرې مۀ کوه، ځکه چې په دېوال باندې خلق به يې واورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9487, '2 Kings 18:27', '2 Kings', 18, 27, '&nbsp;هغۀ ورته ووئيل، ”ستا خيال دا دے څۀ چې يواځې تۀ او بادشاه هغه خلق يئ چې زما نېک تاسو ته د دې هر څۀ وئيلو دپاره رالېږلے يم؟ نه، زۀ هم هغه خلقو ته وايم کوم چې په دېوال ناست دى، ستاسو په شان هغوئ به هم خپل غُل وخورى او خپلې متيازې به وڅښى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9488, '2 Kings 18:28', '2 Kings', 18, 28, '&nbsp;بيا هغه آفسر ودرېدو او په عبرانۍ کښې يې آواز وکړو، ”د لوئ بادشاه، د اسور د بادشاه خبره واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9489, '2 Kings 18:29', '2 Kings', 18, 29, '&nbsp;بادشاه داسې وائى چې حزقياه مو دوکه نۀ کړى. حزقياه تاسو زما د لاس نه نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9490, '2 Kings 18:30', '2 Kings', 18, 30, '&nbsp;او هغه دې ته مۀ پرېږدئ چې تاسو ته ووائى چې په مالِک خُدائ يقين وکړئ. دا خيال مۀ کوئ چې مالِک خُدائ به تاسو بچ کړى او چې هغه به زمونږ اسورى لښکر ستاسو د ښار قبضه کولو نه ايسار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9491, '2 Kings 18:31', '2 Kings', 18, 31, '&nbsp;حزقياه ته غوږ مۀ نيسئ. د اسور بادشاه تاسو له حُکم درکوى چې د ښار نه راوځئ او ما سره روغه وکړئ. تاسو ته به اجازت وى چې د خپلو د انګورو باغونو نه انګور خورئ او د اينځر د ونو نه اينځر خورئ او د خپلو کُوهيانو نه اوبۀ څښئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9492, '2 Kings 18:32', '2 Kings', 18, 32, '&nbsp;تر دې پورې چې بادشاه تاسو بيا په يو داسې مُلک کښې آباد کړى لکه چې ستاسو خپل وى، چې هلته د انګورو باغونه وى چې تاسو له مے درکوى او چې هلته د روټۍ تيارولو دپاره غله وى، هغه د زيتُونو د ونو، د زيتُونو تېلو او د شاتو مُلک دے. کۀ تاسو هغه څۀ کوئ چې څۀ حُکم يې درکوى، نو تاسو به نۀ مرئ او ژوندى به يئ. حزقياه مو چې دوکه نۀ کړى چې درته ووائى چې مالِک خُدائ به مو بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9493, '2 Kings 18:33', '2 Kings', 18, 33, '&nbsp;د نورو قومونو خُدايانو خپل خلق د اسور د بادشاه نه کله بچ کړى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9494, '2 Kings 18:34', '2 Kings', 18, 34, '&nbsp;د حمات او ارفاد خُدايان اوس چرته دى؟ د سفروائم، هينع او عِواه خُدايان چرته دى؟ سامريه بل چا بچ کړے شو څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9495, '2 Kings 18:35', '2 Kings', 18, 35, '&nbsp;د دې ټولو مُلکونو خُدايانو کله هم خپل مُلک زمونږ د بادشاه نه بچ کړے دے څۀ؟ نو مالِک خُدائ به يروشلم زما نه څنګه بچ کړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9496, '2 Kings 18:36', '2 Kings', 18, 36, '&nbsp;خو خلق خاموش وُو او يوه خبره يې هم نۀ کوله ځکه چې حزقياه حُکم ورکړے وو چې، ”هغۀ له جواب مۀ ورکوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9497, '2 Kings 18:37', '2 Kings', 18, 37, '&nbsp;نو اِلياقيم، شبناه او يوآخ د خفګان نه خپلې جامې وشلولې او هغوئ لاړل او چې د اسور آفسر څۀ وئيلى وُو هغه يې بادشاه ته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9498, '2 Kings 19:1', '2 Kings', 19, 1, '&nbsp;څنګه چې حزقياه بادشاه د هغوئ بيان واورېدو، نو هغۀ د خفګان نه خپلې جامې وشلولې، د ټاټ جامې يې واغوستلې او د مالِک خُدائ کور ته ننوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9499, '2 Kings 19:2', '2 Kings', 19, 2, '&nbsp;هغۀ د محل مشر آفسر اِلياقيم، د دربار منشى شبناه، او مشران اِمامان، د آموص زوئ يشعياه پېغمبر له ولېږل، دې ټولو د ټاټ جامې اغوستې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9500, '2 Kings 19:3', '2 Kings', 19, 3, '&nbsp;هغوئ ته يې ووئيل چې يشعياه له دا پېغام ورسوئ، ”نن د خفګان، ملامتيا او د شرم ورځ ده. مونږ د هغه ښځې په شان يُو چې ماشوم يې پېدا کيږى، خو د پېدا کېدو طاقت نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');